'use strict';
document.querySelectorAll('[data-asset]').forEach(img=>{img.src=window.D9_ASSETS[img.dataset.asset];});
const menu=document.querySelector('.menu-toggle'),nav=document.querySelector('#navigation');
menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));nav.classList.toggle('open',open);});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){nav.classList.remove('open');menu.setAttribute('aria-expanded','false');}});
const people={"ricardo": {"name": "Ricardo Hunt", "role": "Managing Partner", "focus": "Finance & global leadership", "bio": "Ricardo brings more than 35 years of Wall Street experience, with a focus on sustainable growth and leadership of cross-functional teams in domestic and international markets. His entrepreneurial perspective includes building teams and driving operational excellence in emerging and foreign markets."}, "brian": {"name": "Brian Gibbs", "role": "Managing Partner", "focus": "Financial strategy & business development", "bio": "Brian brings more than 25 years of diversified financial services experience. His expertise spans financial management, strategic business development, and process improvement, supported by a commitment to strong client relationships and service."}, "courtney": {"name": "Courtney Hunt", "role": "Managing Partner", "focus": "Engineering & infrastructure", "bio": "Courtney is an engineer and experienced project manager whose work spans right-of-way oversight, planning, design, buildout, maintenance, and enhancements for major infrastructure projects. His experience includes licensing, leasing, permits, and the operation of large, scalable facilities."}, "douglas": {"name": "Douglas Patrick", "role": "Managing Partner", "focus": "Sales, operations & regulatory experience", "bio": "Douglas is a former sales executive with leadership experience across 10 New Jersey retail locations. His background combines sales, marketing, and product development with financial services experience as a Bank Examiner and Principal Examiner for two major US regulatory agencies."}, "kurt": {"name": "Kurt Parra", "role": "Principal \u00b7 Managing Partner", "focus": "Business affairs & supply chain", "bio": "Kurt oversees business affairs and brings more than 12 years of experience as a Chief Financial Officer and Chief Supply Chain Officer for private equity-backed companies. He entered the cannabis industry in 2014 through an investment in a Los Angeles cultivation business and its subsequent successful exit."}, "markus": {"name": "Markus Kashinsky", "role": "Principal \u00b7 Managing Member", "focus": "Controlled-environment agriculture", "bio": "Markus has worked in controlled-environment agriculture since 2012. His experience includes leading the design, development, and integration of more than 300 cannabis cultivation and manufacturing facilities, with specialized engineering designs implemented in mechanical systems nationwide."}, "david": {"name": "David Holmes", "role": "Founding Member \u00b7 Cultivation", "focus": "Cultivation expertise", "bio": "David brings more than 20 years of cannabis cultivation experience, including responsibility for thousands of harvests across eight facilities in multiple states. In 2019, he received the Lifetime Cultivation Achievement Award at the Global Cannabis Business Awards."}};
const dialog=document.querySelector('#lightbox');let opener;
dialog.classList.add('bio-card');
const cardBody=document.createElement('div');cardBody.className='bio-card-body';
cardBody.append(document.querySelector('#lightbox-title'));
for(const [id,className] of [['bio-role','bio-role'],['bio-focus','bio-focus'],['bio-text','bio-text']]){const paragraph=document.createElement('p');paragraph.id=id;paragraph.className=className;cardBody.append(paragraph);}
dialog.append(cardBody);

document.querySelectorAll('[data-lightbox]').forEach(button=>button.addEventListener('click',()=>{opener=button;document.querySelector('#lightbox-image').src=window.D9_ASSETS[button.dataset.lightbox];document.querySelector('#lightbox-image').alt=button.dataset.name;const person=people[button.dataset.lightbox];document.querySelector('#lightbox-title').textContent=person.name;document.querySelector('#bio-role').textContent=person.role;document.querySelector('#bio-focus').textContent=person.focus;document.querySelector('#bio-text').textContent=person.bio;dialog.showModal();document.body.style.overflow='hidden';}));
dialog.querySelector('.close').addEventListener('click',()=>dialog.close());
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
dialog.addEventListener('close',()=>{document.body.style.overflow='';opener?.focus();});
// Projected, depth-sorted DNA sculpture. No external animation library or video download.
const canvas=document.querySelector('#dna');
if(canvas){const ctx=canvas.getContext('2d'),reduce=matchMedia('(prefers-reduced-motion: reduce)');let paused=reduce.matches,frame=0,last=0,angle=0,w=0,h=0;
function resize(){const r=canvas.getBoundingClientRect();w=r.width;h=r.height;const d=Math.min(devicePixelRatio||1,2);canvas.width=w*d;canvas.height=h*d;ctx.setTransform(d,0,0,d,0,0);draw();}
function point(t,side){let a=t*2.6+angle+side*Math.PI;let z=Math.sin(a),x=Math.cos(a)*w*.21;let y=(t/Math.PI)*h*.52;return{x:w*.54+x+y*.18,y:h*.5+y,z};}
function line(a,b,width,alpha){const g=ctx.createLinearGradient(a.x,a.y,b.x,b.y);g.addColorStop(0,`rgba(108,157,124,${alpha})`);g.addColorStop(.45,`rgba(233,249,229,${alpha})`);g.addColorStop(.65,`rgba(163,193,170,${alpha})`);g.addColorStop(1,`rgba(56,108,77,${alpha})`);ctx.strokeStyle=g;ctx.lineWidth=width;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke();}
function sphere(x,y,r,alpha){const g=ctx.createRadialGradient(x-r*.35,y-r*.4,0,x,y,r);g.addColorStop(0,`rgba(246,255,242,${alpha})`);g.addColorStop(.2,`rgba(194,221,195,${alpha})`);g.addColorStop(.55,`rgba(79,131,96,${alpha})`);g.addColorStop(.85,`rgba(11,48,29,${alpha})`);g.addColorStop(1,`rgba(175,207,176,${alpha*.7})`);ctx.fillStyle=g;ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fill();}
function draw(){ctx.clearRect(0,0,w,h);let parts=[];for(let t=-3.8;t<3.8;t+=.047){for(let s=0;s<2;s++){const a=point(t,s),b=point(t+.05,s);parts.push({z:a.z,run:()=>{const depth=(a.z+1)/2;line(a,b,8+depth*12,.3+depth*.65);line({x:a.x-2,y:a.y},{x:b.x-2,y:b.y},1.8,.25+depth*.55);}});}}for(let t=-3.7;t<3.7;t+=.29){let a=point(t,0),b=point(t,1);parts.push({z:-.1,run:()=>{line(a,b,5,.52);sphere(a.x,a.y,6,.85);sphere(b.x,b.y,6,.85);}});}parts.sort((a,b)=>a.z-b.z).forEach(p=>p.run());for(let i=0;i<14;i++){let x=w*(.12+(Math.sin(i*7.2)*.5+.5)*.8)+Math.sin(angle*.4+i)*14,y=h*((i*.193)%1)+Math.cos(angle*.5+i)*16;sphere(x,y,3+(i%4)*3,.2+(i%3)*.12);}}
function tick(now){if(!paused&&!document.hidden){angle+=(Math.min(now-last,40)||16)*.00018;draw();}last=now;frame=requestAnimationFrame(tick);}
reduce.addEventListener('change',()=>{paused=reduce.matches;draw();});new ResizeObserver(resize).observe(canvas);frame=requestAnimationFrame(tick);}

document.querySelectorAll('[data-lightbox]').forEach(button=>button.setAttribute('aria-label','Read biography of '+button.dataset.name));

const contactForm=document.querySelector('#contact-form');
if(contactForm)contactForm.addEventListener('submit',e=>{e.preventDefault();const data=new FormData(contactForm);const text=['Double9 Ventures inquiry','Name: '+data.get('name'),'Email: '+data.get('email'),'Organization: '+data.get('organization'),'Interest: '+data.get('interest'),'','Message:',data.get('message')].join('\n');const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download='Double9-inquiry.txt';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);document.querySelector('#form-status').textContent='Your inquiry was downloaded. No message has been sent.';});
